// ============================================================
// CODEX ATLAS — FORGE FX PANEL
// ============================================================
//
// Phase 23.1c RETRY (2026-05-25 NIGHT) — fresh carve.
//
// Lifted from src/js/views/forge.js (`wireFXPanel()`, lines
