      'tl-label-size':    'labelSize',
      'tl-axis-opacity':  'axisOpacity',
      'tl-axis-width':    'axisWidth',
      'tl-grid-opacity':  'gridOpacity',
      'tl-grid-width':    'gridWidth',
      'tl-yr0-opacity':   'yr0Opacity',
      'tl-yr0-size':      'yr0Size',
      'tl-yr0-width':     'yr0Width',
