      tipCurrentRow = row;
      tipEl.innerHTML = buildTipHtml(row);
      tipEl.setAttribute('data-tier', row.getAttribute('data-tier') || 'T1');
      tipEl.setAttribute('data-risky', row.getAttribute('data-edge-risky') === '1' ? '1' : '0');
